// === Tab: mySketch ===
function setup() {
  createCanvas(windowWidth, windowHeight);
}
var rotacion = 0
var circulo = 180
var frecuencia = 7e-6
var color
var tamaño
function draw() {
  background(0);

  translate(width/2, height/2);
  rotate(radians(rotacion));
  ellipseMode(RADIUS);
  for(a=0;a <=2000;a++){
    circulo= 130 + (height/3)*sin(frameCount*frecuencia*a);
    color=map(circulo,255,0,255,70);
    tamaño=map(circulo,150,100,4.5,3.5);
    noStroke()
  	fill(color,abs(sin(millis()*1e-4)*255),abs(cos(frameCount*0.01)*255))
  	ellipse(circulo*sin(a),circulo*cos(a),tamaño)
		rotacion += 1e-9
  }
}

